insert into public.product_configuration_profiles(product_id,product_kind,source_category,source_reference,configuration_attribute_count,configuration_row_count,bom_count,review_note,price_status,historical_price_min,historical_price_median,historical_price_max,last_sale_at,source_file,source_row)
select p.id,s.profile->>'product_kind',s.profile->>'source_category',s.profile->>'source_reference',nullif(s.profile->>'configuration_attribute_count','')::integer,nullif(s.profile->>'configuration_row_count','')::integer,nullif(s.profile->>'bom_count','')::integer,s.profile->>'review_note',s.profile->>'price_status',nullif(s.profile->>'historical_price_min','')::numeric,nullif(s.profile->>'historical_price_median','')::numeric,nullif(s.profile->>'historical_price_max','')::numeric,nullif(s.profile->>'last_sale_at','')::timestamptz,s.profile->>'source_file',nullif(s.profile->>'source_row','')::integer from source s join public.products p on p.code=s.code
on conflict(product_id) do update set product_kind=excluded.product_kind,source_category=excluded.source_category,source_reference=excluded.source_reference,configuration_attribute_count=excluded.configuration_attribute_count,configuration_row_count=excluded.configuration_row_count,bom_count=excluded.bom_count,review_note=excluded.review_note,price_status=excluded.price_status,historical_price_min=excluded.historical_price_min,historical_price_median=excluded.historical_price_median,historical_price_max=excluded.historical_price_max,last_sale_at=excluded.last_sale_at,source_file=excluded.source_file,source_row=excluded.source_row,imported_at=now();
